// Package catalog is the part of web/shared/catalog.js the server needs: countries (for the
// lead finder's search regions), focus-industry search phrases, and the trigger, step and
// condition names automations may use. catalog.json is generated by scripts/gen-catalog.js.
package catalog

import (
	_ "embed"
	"encoding/json"
	"slices"
	"strings"
)

type Country struct {
	Code   string `json:"code"`
	Name   string `json:"name"`
	Region string `json:"region"` // DuckDuckGo region
}

type Industry struct {
	Name     string   `json:"name"`
	Keywords []string `json:"keywords"`
}

type Catalog struct {
	Countries       []Country  `json:"countries"`
	FocusIndustries []Industry `json:"focus_industries"`
	Triggers        []string   `json:"triggers"`
	StepTypes       []string   `json:"step_types"`
	StopConditions  []string   `json:"stop_conditions"`
}

//go:embed catalog.json
var raw []byte

var C = func() Catalog {
	var c Catalog
	if err := json.Unmarshal(raw, &c); err != nil {
		panic("catalog: " + err.Error())
	}
	return c
}()

func ByCode(code string) *Country {
	code = strings.ToUpper(code)
	for i := range C.Countries {
		if C.Countries[i].Code == code {
			return &C.Countries[i]
		}
	}
	return nil
}

// CountryName is the name for an ISO code, or v itself.
func CountryName(v string) string {
	if c := ByCode(v); c != nil {
		return c.Name
	}
	return v
}

// IndustryKeywords are the search phrases for an industry (focus industries have several).
func IndustryKeywords(name string) []string {
	for _, i := range C.FocusIndustries {
		if i.Name == name {
			return slices.Clone(i.Keywords)
		}
	}
	if name == "" {
		return nil
	}
	return []string{name}
}

func IsTrigger(t string) bool  { return slices.Contains(C.Triggers, t) }
func IsStepType(t string) bool { return slices.Contains(C.StepTypes, t) }
